begin;
create temporary table evidence_assertions(label text,passed boolean,detail text);
alter table evidence_assertions enable row level security;
create policy temporary_assertions on evidence_assertions for all to anon,authenticated using(true) with check(true);
grant select,insert on evidence_assertions to authenticated,anon;
do $$begin execute format('grant usage on schema %I to authenticated,anon',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end$$;
create function pg_temp.ok(value boolean,label text) returns boolean language plpgsql as $$begin insert into pg_temp.evidence_assertions values(label,coalesce(value,false),null);return value;end$$;
create function pg_temp.denied(command text,expected text,label text) returns boolean language plpgsql as $$declare code text:='00000';detail text;begin begin execute command;exception when others then get stacked diagnostics code=returned_sqlstate,detail=message_text;end;insert into pg_temp.evidence_assertions values(label,code=expected,case when code<>expected then code||':'||coalesce(detail,'No error')end);return code=expected;end$$;
insert into auth.users(id,email) values('a9200000-0000-0000-0000-000000000001','evidence-c1@example.test'),('a9200000-0000-0000-0000-000000000002','evidence-c2@example.test'),('a9200000-0000-0000-0000-000000000003','evidence-staff@example.test');
insert into vb_private.staff_members(user_id) values('a9200000-0000-0000-0000-000000000003');
insert into public.vb_clients(id,name,client_type,contact_name,portal_enabled) values('b9200000-0000-0000-0000-000000000001','Evidence fixture one','business','Fictional',true),('b9200000-0000-0000-0000-000000000002','Evidence fixture two','business','Fictional',true);
insert into public.vb_marks(id,client_id,name,mark_type,status) values('c9200000-0000-0000-0000-000000000001','b9200000-0000-0000-0000-000000000001','EVIDENCE ONE','word','not_filed'),('c9200000-0000-0000-0000-000000000002','b9200000-0000-0000-0000-000000000002','EVIDENCE TWO','word','not_filed');
insert into vb_private.client_memberships(client_id,user_id) values('b9200000-0000-0000-0000-000000000001','a9200000-0000-0000-0000-000000000001'),('b9200000-0000-0000-0000-000000000002','a9200000-0000-0000-0000-000000000002');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9200000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select public.vb_reserve_evidence('e9200000-0000-0000-0000-000000000001','b9200000-0000-0000-0000-000000000001','c9200000-0000-0000-0000-000000000001',jsonb_build_object('kind','webpage','capturedOn',current_date,'sourceUrl','https://example.test','filename','fixture.png','mimeType','image/png','byteSize',68,'sha256',repeat('a',64)));
select public.vb_reserve_evidence('e9200000-0000-0000-0000-000000000002','b9200000-0000-0000-0000-000000000001','c9200000-0000-0000-0000-000000000001',jsonb_build_object('kind','webpage','capturedOn',current_date,'sourceUrl','https://example.test','filename','fixture.png','mimeType','image/png','byteSize',68,'sha256',repeat('a',64)));
reset role;
insert into storage.objects(bucket_id,name,metadata) values('vb-evidence','b9200000-0000-0000-0000-000000000001/c9200000-0000-0000-0000-000000000001/e9200000-0000-0000-0000-000000000001.png','{"size":68,"mimetype":"image/png"}');
select public.vb_finish_evidence('e9200000-0000-0000-0000-000000000001','a9200000-0000-0000-0000-000000000001');
insert into storage.objects(bucket_id,name,metadata) values('vb-evidence','b9200000-0000-0000-0000-000000000001/c9200000-0000-0000-0000-000000000001/e9200000-0000-0000-0000-000000000002.png','{"size":68,"mimetype":"image/png"}');
select public.vb_finish_evidence('e9200000-0000-0000-0000-000000000002','a9200000-0000-0000-0000-000000000001');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9200000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}',true);
select pg_temp.denied($$select public.vb_remove_evidence('e9200000-0000-0000-0000-000000000001','b9200000-0000-0000-0000-000000000001')$$,'42501','Other client cannot remove evidence');
select set_config('request.jwt.claims','{"sub":"a9200000-0000-0000-0000-000000000003","role":"authenticated","aal":"aal1"}',true);
select pg_temp.denied($$select public.vb_remove_evidence('e9200000-0000-0000-0000-000000000001','b9200000-0000-0000-0000-000000000001')$$,'42501','Attorney without MFA cannot remove');
select set_config('request.jwt.claims','{"sub":"a9200000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select pg_temp.denied($$select public.vb_remove_evidence('e9200000-0000-0000-0000-000000000001','b9200000-0000-0000-0000-000000000002')$$,'42501','Wrong client scope cannot remove');
select public.vb_remove_evidence('e9200000-0000-0000-0000-000000000001','b9200000-0000-0000-0000-000000000001');
select pg_temp.ok((select count(*)=0 from public.vb_evidence where id='e9200000-0000-0000-0000-000000000001'),'Removed item hidden from client');
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='vb-evidence' and name like '%e9200000-0000-0000-0000-000000000001.png'),'Removed image cannot be downloaded by client');
select pg_temp.ok((select count(*)=1 from public.vb_evidence where id='e9200000-0000-0000-0000-000000000002'),'Other upload remains visible');
select public.vb_remove_evidence('e9200000-0000-0000-0000-000000000001','b9200000-0000-0000-0000-000000000001');
select pg_temp.denied($$update public.vb_evidence set removed_at=null,removed_by=null$$,'42501','Client cannot bypass private recovery');
reset role;
select pg_temp.ok((select count(*)=1 from public.vb_evidence where id='e9200000-0000-0000-0000-000000000001' and removed_at is not null and removed_by='a9200000-0000-0000-0000-000000000001'),'Original record and removing client retained privately');
select pg_temp.ok((select count(*)=1 from storage.objects where bucket_id='vb-evidence' and name like '%e9200000-0000-0000-0000-000000000001.png'),'Original file retained privately');
select pg_temp.denied($$select public.vb_finish_evidence('e9200000-0000-0000-0000-000000000001','a9200000-0000-0000-0000-000000000001')$$,'42501','Upload retry cannot resurrect removed evidence');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9200000-0000-0000-0000-000000000003","role":"authenticated","aal":"aal2"}',true);
select pg_temp.ok((select count(*)=0 from public.vb_evidence where id='e9200000-0000-0000-0000-000000000001'),'Removed item hidden from attorney');
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='vb-evidence' and name like '%e9200000-0000-0000-0000-000000000001.png'),'Removed image cannot be downloaded by attorney');
select public.vb_remove_evidence('e9200000-0000-0000-0000-000000000002','b9200000-0000-0000-0000-000000000001');
select pg_temp.ok((select count(*)=0 from public.vb_evidence where client_id='b9200000-0000-0000-0000-000000000001'),'MFA attorney removal hides remaining item');
reset role;
select pg_temp.ok((select count(*)=2 from public.vb_evidence where client_id='b9200000-0000-0000-0000-000000000001' and removed_at is not null),'Both originals retained for recovery');
select pg_temp.ok((select removed_by='a9200000-0000-0000-0000-000000000003' from public.vb_evidence where id='e9200000-0000-0000-0000-000000000002'),'Removing attorney recorded');
select pg_temp.ok((select count(*)=2 from storage.objects where bucket_id='vb-evidence' and name like 'b9200000%'),'Both stored files retained');
set local role anon;
select pg_temp.denied($$select public.vb_remove_evidence('e9200000-0000-0000-0000-000000000002','b9200000-0000-0000-0000-000000000001')$$,'42501','Signed-out removal denied');
reset role;
select jsonb_build_object('executed',count(*),'all_passed',bool_and(passed),'assertions',jsonb_agg(to_jsonb(a))) as removal_results from pg_temp.evidence_assertions a;
rollback;
